    static CdR12bTerrainAssets terrain,equalTerrain;static CdR12bPlayerAssets player;static final int SLOT=45;
    @BeforeAll static void media()throws Exception{String root=System.getProperty("soniccd.media.root");org.junit.jupiter.api.Assumptions.assumeTrue(root!=null&&!root.isBlank(),"Explicit Sonic CD media root");Path cue;try(var paths=Files.list(Path.of(root).resolve("USA"))){var cues=paths.filter(p->p.toString().toLowerCase(Locale.ROOT).endsWith(".cue")).toList();assertEquals(1,cues.size());cue=cues.getFirst();}try(var p=CdProgramAssets.open(cue,Optional.of(CdReleaseVariant.USA),Optional.empty())){terrain=CdR12bTerrainAssets.fromPrograms(p);equalTerrain=CdR12bTerrainAssets.fromPrograms(p);player=CdR12bPlayerAssets.fromPrograms(p);}}
    @Test void metadataAndLegacyPresenceOwnersRemainSeparate(){var a=CdActiveAnimal.Assets.fromAct2PastAssets(terrain.objects());assertSame(terrain.objects().flyingAnimal(),a.flying());assertSame(terrain.objects().groundAnimal(),a.ground());assertSame(terrain.objects().view(CdR12bObjectAssets.View.ANIMAL_BASE_TILES),a.baseTiles());assertEquals(0x20CEE2,a.flyingMappingsAddress());assertEquals(0x20CEF6,a.groundMappingsAddress());var h=new H();var old=CdAnimal.fromAct2PastAssets(h.p,terrain);var before=h.p.capture();assertEquals(CdAnimal.UnsupportedBoundary.PROJECTOR_DESTROYED_BODY,assertThrows(CdAnimal.UnsupportedAnimal.class,()->old.run(SLOT,new CdAnimal.Globals(0,0,1,0,0x1200))).boundary());same(before,h.p,Set.of());}
    @Test void activeFactoryKeepsInactiveAndBadFuturePresenceBranchesAndAdmitsKnownGoodFuture(){var h=new H();h.destroyed=0;h.act=255;var before=h.p.capture();h.run();same(before,h.p,Set.of());assertEquals(0,h.draws);var bad=new H();bad.time=2;bad.failGood=false;bad.good=0;bad.run();assertArrayEquals(new byte[64],bad.slot().copyBytes());assertEquals(0,bad.draws);var good=new H();good.time=2;good.failGood=false;good.good=1;good.destroyed=0;good.run();assertEquals(2,good.slot().routine());assertEquals(0x8461,good.slot().word(TILE));assertEquals(0,good.draws);}
    @Test void actualFactoryRejectsEqualForeignPlacementBeforeMissingHelpers(){var h=new H();var before=h.p.capture();assertThrows(IllegalArgumentException.class,()->CdAnimal.fromAct2PastAssets(h.p,equalTerrain,player,null,null,null,null,null,null));assertThrows(IllegalArgumentException.class,()->CdAnimal.fromAct2PastAssets(new CdObjectPlacementRuntime(terrain.placements()),terrain,player,null,null,null,null,null,null));same(before,h.p,Set.of());}
    @Test void normalInitUsesNativeHeaderAnchorsAndTileWithoutDrawingOrMovingFractions(){for(int subtype:new int[]{0,1,0x7F}){var h=new H();h.edit(s->s.moveByte(SUBTYPE,subtype));var before=h.p.capture();var s=h.slot();h.run();var expected=s.addByte(ROUTINE,2).moveByte(SPRITE_FLAGS,4).moveByte(Y_RADIUS,8).moveByte(X_RADIUS,8).moveByte(PRIORITY,4).moveByte(WIDTH,8).moveLong(MAPPINGS,subtype==0?0x20CEE2:0x20CEF6).moveWord(PATA_BATA_ANCHOR_X,s.centreX()).moveWord(TILE,subtype==0?0x84F7:0x4F7);if(subtype==0)expected=expected.moveWord(CHECKPOINT_BALL_Y,s.centreY()).moveByte(SPRITE_FLAGS,5).moveByte(FLAGS,s.flags()^1).moveWord(ANTON_ANCHOR_X,0x101);else expected=expected.moveLong(ROBOT_GENERATOR_SCHEDULE,0x10000).moveLong(PATA_BATA_X_DELTA,-0x40000);assertEquals(expected,h.slot());assertEquals(0,h.draws);same(before,h.p,Set.of(SLOT));}}
    @Test void hologramInitNeverMovesOrAnimatesAndKeepsTheActualNativePriorityDifference(){for(int subtype:new int[]{0x80,0x81}){var h=new H();h.edit(s->s.moveByte(SUBTYPE,subtype).moveWord(EXPLOSION_POINTS_FRAME,0xD800));var before=h.slot();h.run();assertEquals(4,h.slot().routine());assertEquals(subtype==0x80?3:4,h.slot().unsignedByte(PRIORITY));assertEquals(subtype==0x80?1:0,h.slot().unsignedByte(ANIMATION));assertEquals(before.longBits(X_POSITION),h.slot().longBits(X_POSITION));assertEquals(before.longBits(Y_POSITION),h.slot().longBits(Y_POSITION));assertEquals(0,h.draws);assertEquals(before.flags()^1,h.slot().flags());}}
    @Test void flyingHologramUsesActualParentAndSharedSineButPhaseMultipleOf128ReturnsBeforeDraw(){var h=new H();h.edit(s->s.moveByte(SUBTYPE,0x80).moveWord(EXPLOSION_POINTS_FRAME,0xD800));h.run();var anchor=h.slot();h.run();var values=h.math.calcSine(0);assertEquals((anchor.word(PATA_BATA_ANCHOR_X)+(values.cosine()>>3))&65535,h.slot().centreX());assertEquals(anchor.centreY(),h.slot().centreY());assertEquals(4,h.slot().unsignedByte(CHECKPOINT_ACTIVE));assertEquals(1,h.draws);h.edit(s->s.moveByte(CHECKPOINT_ACTIVE,124));int flips=h.slot().spriteFlags();h.run();assertEquals(128,h.slot().unsignedByte(CHECKPOINT_ACTIVE));assertEquals(flips^1,h.slot().spriteFlags());assertEquals(1,h.draws);}
    @Test void groundHologramUsesOnlyParentAnimationDrawAndDeletesWhenParentInvalid(){var h=new H();h.edit(s->s.moveByte(SUBTYPE,0x81).moveWord(EXPLOSION_POINTS_FRAME,0xD800));h.run();var before=h.slot();h.run();assertEquals(before.longBits(X_POSITION),h.slot().longBits(X_POSITION));assertEquals(before.longBits(Y_POSITION),h.slot().longBits(Y_POSITION));assertEquals(1,h.draws);assertTrue(h.angles.isEmpty());h.p.pool().write(h.p.pool().state(32).moveByte(TAMABBOH_MISSILE_DIRECTION,0xFF));var deleted=h.run();assertTrue(deleted.deleted(),"The active animal wrapper must expose its completed native deletion");assertArrayEquals(new byte[64],h.slot().copyBytes());assertEquals(1,h.draws);}
    @Test void normalFlyingUsesByteBorrowReversalAndRetainsAnchorAndFractions(){var h=new H();h.run();h.edit(s->s.moveByte(CHECKPOINT_ACTIVE,127).moveByte(SWING_COUNT,1));int flips=h.slot().flags();var before=h.slot();h.run();assertEquals(127,h.slot().unsignedByte(CHECKPOINT_ACTIVE));assertEquals(0xFF,h.slot().unsignedByte(SWING_COUNT));assertEquals(flips^1,h.slot().flags());assertEquals(before.word(X_FRACTION),h.slot().word(X_FRACTION));assertEquals(before.word(Y_FRACTION),h.slot().word(Y_FRACTION));assertEquals(before.word(PATA_BATA_ANCHOR_X),h.slot().word(PATA_BATA_ANCHOR_X));assertEquals(1,h.draws);}
    @Test void groundMovementPublishesRealReachedAngleStoresThenNativeBounceFromActualTerrain(){var h=new H();h.edit(s->s.moveByte(SUBTYPE,1));h.run();var before=h.slot();var moved=before.addLong(X_POSITION,before.longBits(ROBOT_GENERATOR_SCHEDULE)).addLong(Y_POSITION,before.longBits(PATA_BATA_X_DELTA)).addLong(PATA_BATA_X_DELTA,0x2000);var probe=CdObjectCollisionCheck.objGetFloorDist(h.probes,moved);h.run();assertFalse(h.angles.isEmpty());assertEquals(0,h.angles.getFirst().value());assertEquals(probe.primaryAngle(),h.angle);assertEquals((before.longBits(X_POSITION)+0x10000),h.slot().longBits(X_POSITION));if(probe.distance()<0){assertEquals(-0x10000,h.slot().longBits(ROBOT_GENERATOR_SCHEDULE));assertEquals(-0x40000,h.slot().longBits(PATA_BATA_X_DELTA));}else assertEquals(-0x3E000,h.slot().longBits(PATA_BATA_X_DELTA));assertEquals(1,h.draws);}
    @Test void reachedAngleOwnerFailureRetainsGroundMotionBeforeFloorWithoutInventingAnAngle(){var h=new H();h.edit(s->s.moveByte(SUBTYPE,1));h.run();var before=h.slot();var fault=new Fault();h.hook=c->{if(c instanceof CdActiveAnimal.PrimaryAngleCall)throw fault;};assertSame(fault,assertThrows(Fault.class,h::run));assertEquals(before.longBits(X_POSITION)+0x10000,h.slot().longBits(X_POSITION));assertEquals(before.longBits(Y_POSITION)-0x40000,h.slot().longBits(Y_POSITION));assertEquals(-0x3E000,h.slot().longBits(PATA_BATA_X_DELTA));assertEquals(0x34,h.angle);assertEquals(0,h.draws);assertFalse(h.body.isCurrentCall(h.last));}
    @Test void badActAndParentAndRoutineStopAtReachedReadAfterTheirOwnPrefixes(){var h=new H();h.act=0xFF;var old=h.slot();assertEquals(CdActiveAnimal.UnsupportedBoundary.BASE_TILE_READ,assertThrows(CdActiveAnimal.UnsupportedActiveAnimal.class,h::run).boundary());assertEquals(2,h.slot().routine());assertEquals(old.centreX(),h.slot().word(PATA_BATA_ANCHOR_X));assertEquals(0,h.draws);h=new H();h.edit(s->s.moveByte(SUBTYPE,0x80).moveByte(ROUTINE,4).moveWord(EXPLOSION_POINTS_FRAME,0xD001));assertEquals(CdActiveAnimal.UnsupportedBoundary.PARENT_READ,assertThrows(CdActiveAnimal.UnsupportedActiveAnimal.class,h::run).boundary());h=new H();h.edit(s->s.moveByte(ROUTINE,3));assertEquals(CdActiveAnimal.UnsupportedBoundary.ROUTINE_DISPATCH,assertThrows(CdActiveAnimal.UnsupportedActiveAnimal.class,h::run).boundary());}
    @Test void nativeDrawFailureRetainsPrefixAndOriginalReceiptCannotEscapeOrReenter(){var h=new H();h.run();h.hook=c->{assertTrue(h.body.isCurrentCall(c));assertThrows(IllegalStateException.class,h::run);};h.run();assertFalse(h.body.isCurrentCall(h.last));var fault=new Fault();h.hook=c->{if(c instanceof CdActiveAnimal.DrawCall)throw fault;};var before=h.slot();assertSame(fault,assertThrows(Fault.class,h::run));assertNotEquals(before,h.slot());assertFalse(h.body.isCurrentCall(h.last));}
    static final class H{
        final CdObjectPlacementRuntime p=CdObjectPlacementRuntime.fromAssets(terrain,CdAssetBytes.copyOf(new byte[CdObjectPlacementRuntime.SAVED_BANK_BYTES]));final CdPlayerMath math=new CdPlayerMath(player.player());final CdPlayerTerrain probes=CdPlayerTerrain.fromStageTerrain(terrain.terrain());CdAnimal body;int destroyed=1,act=1,angle=0x34,draws,time,good;boolean failGood=true;Object last;Consumer<Object> hook=c->{};final List<CdActiveAnimal.PrimaryAngleCall> angles=new ArrayList<>();
        H(){edit(s->s.moveByte(ID,0x24).moveWord(X,0x1200).moveWord(X_FRACTION,0x1234).moveWord(Y,0x300).moveWord(Y_FRACTION,0x5678));p.pool().write(p.pool().state(32).moveByte(ID,0x2E));body=CdAnimal.fromAct2PastAssets(p,terrain,player,math,probes,c->{hook.accept(c);assertEquals(angle,c.expectedPrimaryAngle());angle=c.value();angles.add(c);},c->{hook.accept(c);draws++;p.pool().write(slot().moveByte(SPRITE_FLAGS,slot().spriteFlags()&127));},new CdActiveAnimal.DispatchObserver(){public void beforePublication(CdActiveAnimal.Publication c){current(c);}public void afterPublication(CdActiveAnimal.Publication c){}public void beforeCall(Object c){current(c);}public void afterCall(Object c){}},new CdActiveAnimal.ReceiptGuard(){public void prepared(Object c){assertTrue(body.isCurrentCall(c));}public void completed(Object c){assertTrue(body.isCurrentCall(c));}});}
        void current(Object c){last=c;assertTrue(body.isCurrentCall(c));if(c instanceof CdActiveAnimal.DrawCall d)assertFalse(body.isCurrentCall(new CdActiveAnimal.DrawCall(d.actualCut(),d.expectedSource())));hook.accept(c);}CdObjectState slot(){return p.pool().state(SLOT);}void edit(UnaryOperator<CdObjectState> f){p.pool().write(f.apply(slot()));}CdAnimal.Result run(){return body.runWithReads(SLOT,new CdActiveAnimal.Reads(){public int act(){return act;}public int primaryAngle(){return angle;}public int timeZone(){return time;}public int goodFuture(){if(failGood)throw new AssertionError("Past body never reads goodFuture");return good;}public int projDestroyed(){return destroyed;}public int timeWarpDir(){return 0;}public int cameraXWord(){return 0x1200;}});}
    }
    static void same(CdObjectPlacementRuntime.Snapshot before,CdObjectPlacementRuntime p,Set<Integer> changed){assertEquals(before.status(),p.status());assertArrayEquals(before.savedFlags().copy(),p.capture().savedFlags().copy());for(var s:before.pool().slots())if(!changed.contains(s.identity().wholeIndex()))assertEquals(s,p.pool().state(s.identity().wholeIndex()));}static class Fault extends RuntimeException{private static final long serialVersionUID=1L;}
